using Lorcaire.Application.Resources;using Lorcaire.Application.Resources.DeleteResource;using Lorcaire.Application.Resources.Persistence;using Lorcaire.Application.Resources.UpdateResource;using Lorcaire.Core.Domain.Areas;using Lorcaire.Core.Domain.Resources;
using Lorcaire.Core.Domain;
namespace Lorcaire.Application.Tests.Resources;
public sealed class ManageResourceHandlersTests{[Fact]public async Task UpdateAndDelete_WorkAndMissingIsReported(){var x=new Resource(ResourceId.New(),AreaId.New(),"Old","Book");var r=new Repo(x);await new UpdateResourceHandler(r).HandleAsync(new(x.Id.Value,"New","Course","Desc"));Assert.Equal("Course",x.Category);await new DeleteResourceHandler(r).HandleAsync(x.Id.Value);await Assert.ThrowsAsync<ResourceNotFoundException>(()=>new DeleteResourceHandler(r).HandleAsync(x.Id.Value));}[Fact]public async Task UpdateFailure_DoesNotPartiallyMutateResource(){var x=new Resource(ResourceId.New(),AreaId.New(),"Old","Book","Original");var r=new Repo(x);await Assert.ThrowsAsync<ArgumentException>(()=>new UpdateResourceHandler(r).HandleAsync(new(x.Id.Value,"New","Course",new string('x',DomainTextLimits.DescriptionMaximumLength+1))));Assert.Equal("Old",x.Name);Assert.Equal("Book",x.Category);Assert.Equal("Original",x.Description);}private sealed class Repo(params Resource[]v):IResourceRepository{private readonly Dictionary<ResourceId,Resource>d=v.ToDictionary(x=>x.Id);public Task AddAsync(Resource x,CancellationToken c=default){d.Add(x.Id,x);return Task.CompletedTask;}public Task<Resource?>GetByIdAsync(ResourceId id,CancellationToken c=default){d.TryGetValue(id,out var x);return Task.FromResult(x);}public Task UpdateAsync(Resource x,CancellationToken c=default){d[x.Id]=x;return Task.CompletedTask;}public Task<bool>DeleteAsync(ResourceId id,CancellationToken c=default)=>Task.FromResult(d.Remove(id));}}
